def capture_route(checkpoint, family, scenario=None):
    """A finite approval replaces every matching Task 8 or Task 11 route row.

    Missing, expired or changed approval denies replay for this checkpoint;
    it never falls back to the broad Docs route. Telemetry scope is unchanged.
    """
    if checkpoint != NARROW_CHECKPOINT and scenario != TASK11_SCENARIO:
        return {'public_pages': PAGES[family]}
    denied = {'public_pages': [], 'capture_tools': VIEW_TOOLS}
    path = HERE / 'capture-route-overrides.json'
    try:
        stat = path.lstat()
        if path.is_symlink() or stat.st_uid != os.getuid() or stat.st_mode & 0o077 or stat.st_size > 16384:
            return denied
        approval = json.loads(path.read_text())
        row = approval['checkpoints'][checkpoint]
        expected = 'https://docs.google.com/document/d/' + NARROW_DOCUMENT + '/mobilebasic'
        expiry = row['expires_at']
        now = time.time()
        if (approval['campaign'] != HERE.name or row['document_id'] != NARROW_DOCUMENT
                or scenario == TASK11_SCENARIO and row.get('scenario') != TASK11_SCENARIO
                or row['reviewed_body_and_audience'] is not True
                or type(expiry) not in (int, float) or not now < expiry <= now + 86400
                or row['public_pages'] != [expected] or row['review_url'] != expected
                or row['capture_tools'] != VIEW_TOOLS):
            return denied
        for proof in row['proofs']:
            source = HERE / proof['path']
            if (source.is_symlink() or not source.resolve().is_relative_to(HERE)
                    or hashlib.sha256(source.read_bytes()).hexdigest() != proof['sha256']):
                return denied
        if len(row['proofs']) != 2:
            return denied
        return {'public_pages': [expected], 'review_url': expected, 'capture_tools': VIEW_TOOLS}
    except (OSError, ValueError, KeyError, TypeError):
        return denied

def sync_lane(cfg):
    state = qa.load_state(cfg)
    active = state.get('current_run')
    tasks = []
    if active:
        run = qa.load_run(cfg, active)
        label = run['scenario']
        family = ('instamart' if 'instamart' in label else 'nike' if label == 'add-one-pair-640d'
                  else 'apple' if label == 'add-13-inch-3755' else 'github' if label in
                  ('sign-github-saved-a5d4','add-issue-called-c181') else 'goa')
        route = capture_route(active, family, label)
        threads = qa.causal_threads(cfg, run)
        requesters = {cfg.testers[name]['user'] for name in run['testers']}
        keys = set()
        def add(requester, channel, thread, home, session=None):
            context = hashlib.sha256(('v2:' + cfg.team_id + ':' + requester + ':' + str(Path(home).resolve())).encode()).hexdigest()
            key = (requester, channel, thread, context, session)
            if key in keys:
                return
            keys.add(key)
            tasks.append({'team':cfg.team_id,'requester':requester,'channel':channel,'thread':thread,
                'context':context,'session_id':session,'bind_created_session':True,'telemetry_create':True,
                'checkpoint':active, **route, 'resume_public_after_private':True})
        for channel, thread in threads:
            for requester in requesters:
                if channel.startswith('D'):
                    home = cfg.lab_home / 'profiles' / ('slack-' + cfg.team_id.lower() + '-' + requester.lower())
                else:
                    home = cfg.lab_home / 'profiles' / ('slack-' + cfg.team_id.lower() + '-' + channel.lower())
                add(requester, channel, thread, home)
        for path in (cfg.lab_home / '.clanker-cloud/kernel/contexts').glob('*.json'):
            data = json.loads(path.read_text())
            owner = data.get('owner', {})
            if owner.get('team') != cfg.team_id or owner.get('requester') not in requesters:
                continue
            for key, name in data.get('threads', {}).items():
                channel, thread = key.split(':', 1)
                if (channel, thread) not in threads:
                    continue
                entry = data.get('sessions', {}).get(name, {})
                if entry.get('home'):
                    add(owner['requester'],channel,thread,entry['home'],entry.get('session_id'))
        qa.record_kernel_sessions(cfg, run)
    return active, tasks

def sync():
    active_runs, tasks = [], []
    for folder in [HERE, *sorted((HERE/'lanes').glob('*'))]:
        if not folder.is_dir():
            continue
        data = qa.deep_merge(cfg.data, qa.read_json(folder/'config.json', {}))
        data['state_dir'] = str(folder)
        active, rows = sync_lane(qa.Config(data))
        if active:
            active_runs.append(active)
            tasks.extend(rows)
    if len(active_runs) > 4:
        raise RuntimeError('Capture batch exceeds four active benchmark runs')
    payload = {'enabled':bool(active_runs),'campaign':'2026-10-12-corrected','expires_at':time.time()+14400,'tasks':tasks}
    qa.write_json(manifest, payload)
    return {'active_runs':active_runs,'scoped_tasks':len(tasks)}

